#include <omp.h>
#include <vector>
#include <cstddef>

void prefixSum(std::vector<double> const& x, std::vector<double> &output) {
    const std::size_t n = x.size();
    output.resize(n);
    if (n == 0) {
        return;
    }

    // Allocate per-thread storage using the maximum possible team size.
    const int max_threads = omp_get_max_threads();
    std::vector<double> block_sums(static_cast<std::size_t>(max_threads), 0.0);
    std::vector<double> block_offsets(static_cast<std::size_t>(max_threads), 0.0);

    #pragma omp parallel default(none) shared(x, output, block_sums, block_offsets, n)
    {
        const int tid = omp_get_thread_num();
        const int nt  = omp_get_num_threads();

        const std::size_t start = (n * static_cast<std::size_t>(tid)) / static_cast<std::size_t>(nt);
        const std::size_t end   = (n * static_cast<std::size_t>(tid + 1)) / static_cast<std::size_t>(nt);

        // Phase 1: local prefix sum within this thread's block.
        double local_sum = 0.0;
        for (std::size_t i = start; i < end; ++i) {
            local_sum += x[i];
            output[i] = local_sum;
        }
        block_sums[static_cast<std::size_t>(tid)] = local_sum;

        // Phase 2: one thread computes offsets for each block.
        #pragma omp single
        {
            block_offsets[0] = 0.0;
            for (int t = 1; t < nt; ++t) {
                block_offsets[static_cast<std::size_t>(t)] =
                    block_offsets[static_cast<std::size_t>(t - 1)] +
                    block_sums[static_cast<std::size_t>(t - 1)];
            }
        }

        // Phase 3: add the offset from all preceding blocks.
        const double offset = block_offsets[static_cast<std::size_t>(tid)];
        for (std::size_t i = start; i < end; ++i) {
            output[i] += offset;
        }
    }
}
